340	impl ResumePlan {
341	    /// Validate a resume request against the session log and make a plan.
342	    ///
343	    /// `events` is the full session log and `snapshot` is the session
344	    /// snapshot (a custom session can override the snapshot, so the runner
345	    /// reads both). `root_agent_name` is the name of the agent that the
346	    /// runner runs. `input` carries the host resolutions and the new input
347	    /// messages.
348	    ///
349	    /// The checks run in this order: tool items in the input, duplicate
350	    /// resolutions, no open deferrals, unknown deferral ids, unresolved
351	    /// deferrals, a session changed after the deferral, a deferred call that
352	    /// is not in the history, and a handoff path that is too deep.
353	    ///
354	    /// A `root_agent_name` that is not the first name of the handoff path is
355	    /// not an error. The agent then denies every call.
356	    pub fn from_events(
357	        events: &[crate::SessionEvent],
358	        snapshot: &crate::ConversationSnapshot,
359	        root_agent_name: &str,
360	        input: &crate::AgentInput,
361	        max_agent_depth: u32,
362	    ) -> Result<ResumePlan, InvalidResume> {
363	        use crate::{Item, SessionEvent};
364	
365	        // A nested `ContentPart::ToolUse` or `ContentPart::ToolResult` is
366	        // equal to a top-level tool item, so it is rejected too.
367	        let has_tool_part = |content: &[crate::ContentPart]| {
368	            content.iter().any(|p| {
369	                matches!(
370	                    p,
371	                    crate::ContentPart::ToolUse { .. } | crate::ContentPart::ToolResult { .. }
372	                )
373	            })
374	        };
375	        if input.messages.iter().any(|i| match i {
376	            Item::ToolCall { .. } | Item::ToolResult { .. } => true,
377	            Item::UserMessage { content }
378	            | Item::AssistantMessage { content, .. }
379	            | Item::System { content } => has_tool_part(content),
380	        }) {
381	            return Err(InvalidResume::ToolItemsInInput);
382	        }
383	
384	        let resolutions = input.resolutions();
385	        for (n, (id, _)) in resolutions.iter().enumerate() {
386	            if resolutions[..n].iter().any(|(other, _)| other == id) {
387	                return Err(InvalidResume::DuplicateResolution {
388	                    deferral_id: id.clone(),
389	                });
390	            }
391	        }
392	
393	        let open = open_deferral_positions(events);
394	        let Some(&(first, _)) = open.first() else {
395	            return Err(InvalidResume::NoOpenDeferrals);
396	        };
397	
398	        for (id, _) in resolutions {
399	            if !open.iter().any(|(_, c)| c.deferral_id() == id) {
400	                return Err(InvalidResume::UnknownDeferral {
401	                    deferral_id: id.clone(),
402	                });
403	            }
404	        }
405	
406	        let missing: Vec<String> = open
407	            .iter()
408	            .filter(|(_, c)| !resolutions.iter().any(|(id, _)| id == c.deferral_id()))
409	            .map(|(_, c)| c.deferral_id().to_owned())
410	            .collect();
411	        if !missing.is_empty() {
412	            return Err(InvalidResume::UnresolvedDeferrals { missing });
413	        }
414	
415	        if events[first + 1..].iter().any(|e| {
416	            matches!(
417	                e,
418	                SessionEvent::UserMessage { .. }
419	                    | SessionEvent::AssistantMessage { .. }
420	                    | SessionEvent::ToolCalled { .. }
421	            )
422	        }) {
423	            return Err(InvalidResume::SessionModified);
424	        }
425	        let path = open[0].1.handoff_path().to_vec();
426	        if path.is_empty() || open.iter().any(|(_, c)| c.handoff_path() != path) {
427	            return Err(InvalidResume::SessionModified);
428	        }
429	        let handoffs = handoff_indices(events, &path, first)?;
430	
431	        for (_, call) in &open {
432	            let messages = &snapshot.messages;
433	            let found = messages.iter().rposition(
434	                |i| matches!(i, Item::ToolCall { call_id, .. } if call_id == call.call_id()),
435	            );
436	            let valid = found.is_some_and(|p| {
437	                let same_name =
438	                    matches!(&messages[p], Item::ToolCall { name, .. } if name == call.tool());
439	                let answered = messages[p + 1..].iter().any(
440	                    |i| matches!(i, Item::ToolResult { call_id, .. } if call_id == call.call_id()),
441	                );
442	                same_name && !answered
443	            });
444	            if !valid {
445	                return Err(InvalidResume::CallNotInHistory {
446	                    call_id: call.call_id().to_owned(),
447	                });
448	            }
449	        }
450	
451	        // `path` is nonempty here (checked above). Compare the depth, not
452	        // `len > max + 1`: the addition can overflow `usize` on a 32-bit target.
453	        if path.len() - 1 > max_agent_depth as usize {
454	            return Err(InvalidResume::PathTooDeep {
455	                len: path.len(),
456	                max_agent_depth,
457	            });
458	        }
459	
460	        let mut histories = vec![snapshot.messages.clone()];
461	        if root_agent_name == path[0] {
462	            for level in 1..path.len() {
463	                histories.push(agent_view(events, &handoffs, level, events.len()));
464	            }
465	        }
466	        let transfers = (1..path.len())
467	            .map(|level| transfer_calls_before(events, handoffs[level]))
468	            .collect();
469	
470	        let calls = open
471	            .into_iter()
472	            .map(|(_, pending)| {
473	                let resolution = resolutions
474	                    .iter()
475	                    .find(|(id, _)| id == pending.deferral_id())
476	                    .map(|(_, r)| r.clone())
477	                    .expect("every open deferral has a resolution");
478	                PlannedCall {
479	                    pending,
480	                    resolution,
481	                }
482	            })
483	            .collect();
484	
485	        Ok(ResumePlan {
486	            calls,
487	            path,
488	            histories,
489	            transfers,
490	            level: 0,
491	        })
492	    }
