625	/// One transfer call of a handoff response, found by its position.
626	///
627	/// Two calls on the path can have the same call id, so the call id alone
628	/// does not find the call. `later_calls` is the number of `ToolCalled`
629	/// events with the same call id after this call in the log. Each
630	/// conversation on the path holds every call after a transfer call of its
631	/// own level or deeper, so the call is the `ToolCall` item with this call id
632	/// that has `later_calls` such items after it.
633	#[derive(Debug, Clone, PartialEq, Eq)]
634	pub(crate) struct TransferCall {
635	    /// The call id of the transfer call.
636	    pub(crate) call_id: String,
637	    /// The number of later `ToolCalled` events with the same call id.
638	    pub(crate) later_calls: usize,
639	}
640	
641	/// The transfer calls of the handoff at `handoff_at`, in log order.
642	///
643	/// The loop records the transfer `ToolCalled` events of a handoff response
644	/// directly before the `HandoffOccurred` event, with the assistant text of
645	/// that response. A response can hold more than one transfer call; the
646	/// first one names the target. This finds the calls by their position, not
647	/// by their tool name, because a handoff can use a custom tool name.
648	fn transfer_calls_before(events: &[crate::SessionEvent], handoff_at: usize) -> Vec<TransferCall> {
649	    use crate::SessionEvent;
650	    let start = handoff_at
651	        - events[..handoff_at]
652	            .iter()
653	            .rev()
654	            .take_while(|e| {
655	                matches!(
656	                    e,
657	                    SessionEvent::ToolCalled { .. } | SessionEvent::AssistantMessage { .. }
658	                )
659	            })
660	            .count();
661	    (start..handoff_at)
662	        .filter_map(|at| {
663	            match &events[at] {
664	            SessionEvent::ToolCalled { call_id, .. } => Some(TransferCall {
665	                call_id: call_id.clone(),
666	                later_calls: events[at + 1..]
667	                    .iter()
668	                    .filter(|e| {
669	                        matches!(e, SessionEvent::ToolCalled { call_id: id, .. } if id == call_id)
670	                    })
671	                    .count(),
672	            }),
673	            _ => None,
674	        }
675	        })
676	        .collect()
677	}
