245	/// Translate a conversation `Vec<Item>` into OpenAI Responses-API
246	/// `input: [...]` form.
247	///
248	/// Items become `{type: "message", role, content: [parts]}` blocks for
249	/// system/user/assistant; `Item::ToolCall` becomes a
250	/// `function_call` item; `Item::ToolResult` becomes a
251	/// `function_call_output` item. The same standalone-`ToolCall` rule
252	/// applies — there is no special carrier needed because the Responses
253	/// API treats function_call items as top-level.
254	pub(crate) fn to_responses_input(items: &[Item]) -> Value {
255	    let mut out: Vec<Value> = Vec::new();
256	    for item in items {
257	        match item {
258	            Item::System { content } => {
259	                out.push(json!({
260	                    "type": "message",
261	                    "role": "system",
262	                    "content": [{"type": "input_text", "text": text_of(content)}],
263	                }));
264	            }
265	            Item::UserMessage { content } => {
266	                let mut text_parts: Vec<Value> = Vec::new();
267	                let mut hoisted: Vec<Value> = Vec::new();
268	                for p in content {
269	                    match p {
270	                        ContentPart::Text { text } => {
271	                            text_parts.push(json!({"type": "input_text", "text": text}));
272	                        }
273	                        ContentPart::Image { source } => {
274	                            if let Some(url) = media_url(source) {
275	                                text_parts.push(json!({"type": "input_image", "image_url": url}));
276	                            }
277	                        }
278	                        ContentPart::ToolResult { call_id, content } => {
279	                            hoisted.push(json!({
280	                                "type": "function_call_output",
281	                                "call_id": call_id,
282	                                "output": text_of(content),
283	                            }));
284	                        }
285	                        _ => { /* drop reasoning/audio/future variants */ }
286	                    }
287	                }
288	                if !text_parts.is_empty() {
289	                    out.push(json!({"type": "message", "role": "user", "content": text_parts}));
290	                }
291	                out.extend(hoisted);
292	            }
293	            Item::AssistantMessage { content, agent: _ } => {
294	                let parts: Vec<Value> = content
295	                    .iter()
296	                    .filter_map(|p| match p {
297	                        ContentPart::Text { text } => {
298	                            Some(json!({"type": "output_text", "text": text}))
299	                        }
300	                        _ => None,
301	                    })
302	                    .collect();
303	                if !parts.is_empty() {
304	                    out.push(json!({"type": "message", "role": "assistant", "content": parts}));
305	                }
306	                // Hoist nested ToolUse blocks into top-level function_call items.
307	                for p in content {
308	                    if let ContentPart::ToolUse {
309	                        call_id,
310	                        name,
311	                        args,
312	                    } = p
313	                    {
314	                        out.push(json!({
315	                            "type": "function_call",
316	                            "call_id": call_id,
317	                            "name": name,
318	                            "arguments": args.to_string(),
319	                        }));
320	                    }
321	                }
322	            }
323	            Item::ToolCall {
324	                call_id,
325	                name,
326	                args,
327	            } => {
328	                out.push(json!({
329	                    "type": "function_call",
330	                    "call_id": call_id,
331	                    "name": name,
332	                    "arguments": args.to_string(),
333	                }));
334	            }
335	            Item::ToolResult { call_id, content } => {
336	                out.push(json!({
337	                    "type": "function_call_output",
338	                    "call_id": call_id,
339	                    "output": text_of(content),
340	                }));
341	            }
342	            _ => {
343	                // Future Item variants — skip.
344	                tracing::warn!(
345	                    target: "paigasus::openai::translate",
346	                    "unknown Item variant; skipping in to_responses_input"
347	                );
348	            }
349	        }
350	    }
351	    Value::Array(out)
352	}
