1	//! Maps [`AgentEvent`]s onto AG-UI event frames, with bracketing.
2	//!
3	//! # Why bracketing lives here
4	//!
5	//! `TokenDelta`/`ReasoningDelta` are bare fragments, but AG-UI requires balanced
6	//! `*_START` … `*_CONTENT` … `*_END` triples, and `STEP_STARTED` has no
7	//! "turn finished" event to close it. [`EventMapper`] owns those pairings so no
8	//! transport has to.
9	//!
10	//! # Ordering
11	//!
12	//! `ToolCallDelta` is emitted while the model stream drains; the matching
13	//! `ToolCallItem` only afterwards. `TOOL_CALL_START` is therefore derived from the
14	//! *first delta* for a call id — its `name` is populated only on that first delta,
15	//! which is exactly the START payload — and never from `ToolCallItem`, which would
16	//! put START after the ARGS frames it must precede.
17	//!
18	//! # One active tool-call span
19	//!
20	//! AG-UI permits a single active tool call at a time, but core's `ToolCallDelta`s for
21	//! different ids may interleave freely (`paigasus-helikon-core/src/model.rs:56`) and
22	//! its `ToolCallItem`s carry no ordering guarantee. Reconciling the two is what
23	//! [`EventMapper`]'s tool-call state exists for, and it owes an AG-UI client three
24	//! things: spans never overlap, one call id maps to exactly one span, and an id's
25	//! args reach the client in receipt order inside that span (a client concatenating
26	//! `TOOL_CALL_ARGS` deltas would otherwise rebuild malformed JSON). Deltas for an id
27	//! that arrive while another call holds the span are therefore buffered, not
28	//! interleaved, and replayed when that id takes the span or is flushed.
29	
30	use std::collections::{HashMap, HashSet};
31	
32	use paigasus_helikon_core::{AgentEvent, ContentPart, Item};
33	use serde_json::Value;
34	
35	use crate::agui::types::event;
36	
37	/// Which text-like pair is currently open.
38	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
39	enum OpenText {
40	    /// No text or thinking block is open.
41	    None,
42	    /// A `TEXT_MESSAGE_START` … `TEXT_MESSAGE_END` pair is open.
43	    Message,
44	    /// A `THINKING_TEXT_MESSAGE_START` … `THINKING_TEXT_MESSAGE_END` pair is open.
45	    Thinking,
46	}
47	
48	/// Which text-like pair [`EventMapper::open_text`] should open. Two variants, not
49	/// [`OpenText`]'s three — opening "no block" is not a request this method can be asked
50	/// to satisfy, so the type itself rules that call out rather than the body handling it.
51	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
52	enum TextKind {
53	    /// Open a `TEXT_MESSAGE_START` … `TEXT_MESSAGE_END` pair.
54	    Message,
55	    /// Open a `THINKING_TEXT_MESSAGE_START` … `THINKING_TEXT_MESSAGE_END` pair.
56	    Thinking,
57	}
58	
59	/// Stateful `AgentEvent` → AG-UI frame mapper for exactly one run.
60	pub(crate) struct EventMapper {
61	    /// Client-supplied (or generated) thread id, echoed in `RUN_STARTED`/`RUN_FINISHED`.
62	    thread_id: String,
63	    /// Client-supplied (or generated) run id, echoed in `RUN_STARTED`/`RUN_FINISHED`.
64	    run_id: String,
65	    /// Which text-like pair (message or thinking) is currently open, if any.
66	    open_text: OpenText,
67	    /// Id of the currently-open text or thinking message.
68	    current_message: String,
69	    /// Monotonic counter behind `msg-N` ids. Stream-local uniqueness is all AG-UI
70	    /// requires, and deterministic ids let tests assert exact frame sequences.
71	    next_message: u32,
72	    /// Whether the current turn's assistant text has already been streamed via
73	    /// `TokenDelta`. Distinct from `open_text == OpenText::Message`: a `ToolCallDelta`
74	    /// closes the text block (via `close_text`) well before the matching
75	    /// `MessageOutput` arrives, so checking "is a message open right now" would miss
76	    /// that this text was already streamed and re-emit it.
77	    streamed_text: bool,
78	    /// Id of the call currently being streamed — has an open `TOOL_CALL_START` and no
79	    /// `TOOL_CALL_END` yet. `None` if no call is currently open.
80	    open_call: Option<String>,
81	    /// Tool name per call id, recorded from whichever `ToolCallDelta` first carries
82	    /// one. Only a call's *first* delta populates `name`, but the delta that finally
83	    /// opens that call's span may be a continuation (its buffer resuming, or a
84	    /// revisit), so the name has to be remembered rather than read off the delta at
85	    /// hand — otherwise those spans render as `"unknown"`.
86	    call_names: HashMap<String, String>,
87	    /// Calls whose deltas arrived while a *different* call was open: `(call_id,
88	    /// accumulated args)`. AG-UI permits only one active tool-call span at a
89	    /// time, while core's `ToolCallDelta`s for different ids may interleave freely
90	    /// (`paigasus-helikon-core/src/model.rs:56`) — buffering instead of closing and
91	    /// resuming preserves every args chunk exactly once and never emits an unmatched
92	    /// `TOOL_CALL_END`. A `Vec`, not a map, so flush order is deterministic.
93	    buffered_calls: Vec<(String, String)>,
94	    /// Call ids whose span has been emitted *and* closed. A `ToolCallItem` arrives
95	    /// long after the deltas it describes, by which time the call's span may already
96	    /// be closed — by its own delta path or by a foreign event that interrupted it.
97	    /// Without this record the item's arm cannot tell "already rendered" from "never
98	    /// streamed, synthesize it", and emits a second complete span for one call.
99	    completed_calls: HashSet<String>,
100	    /// Whether a `STEP_STARTED` is currently unmatched.
101	    step_open: bool,
102	}
103	
104	impl EventMapper {
105	    /// Create a mapper for one run.
106	    // Constructed by the AG-UI SSE endpoint (SMA-461 Task 6, src/agui/sse.rs) and the
107	    // AG-UI WebSocket endpoint (SMA-461 Task 7, src/agui/ws.rs), one per run in both.
108	    pub(crate) fn new(thread_id: String, run_id: String) -> Self {
109	        Self {
110	            thread_id,
111	            run_id,
112	            open_text: OpenText::None,
113	            current_message: String::new(),
114	            next_message: 0,
115	            streamed_text: false,
116	            open_call: None,
117	            call_names: HashMap::new(),
118	            buffered_calls: Vec::new(),
119	            completed_calls: HashSet::new(),
120	            step_open: false,
121	        }
122	    }
123	
124	    /// Map one event, emitting any bracketing frames it implies.
125	    // Called per event by both the AG-UI SSE endpoint (SMA-461 Task 6) and the AG-UI
126	    // WebSocket endpoint (SMA-461 Task 7) as each drains an `Agent` run.
127	    pub(crate) fn push(&mut self, ev: &AgentEvent) -> Vec<Value> {
128	        let mut out = Vec::new();
129	        match ev {
130	            AgentEvent::RunStarted { .. } => {
131	                out.push(event::run_started(&self.thread_id, &self.run_id));
132	            }
133	            AgentEvent::TurnStarted { .. } => {
134	                self.close_text(&mut out);
135	                // A tool-call span must not cross the `STEP_FINISHED`/`STEP_STARTED`
136	                // boundary below — it would close inside the *next* step.
137	                self.close_call(&mut out);
138	                self.close_step(&mut out);
139	                self.streamed_text = false;
140	                self.step_open = true;
141	                out.push(event::step_started("turn"));
142	            }
143	            AgentEvent::TokenDelta { text } => {
144	                self.close_call(&mut out);
145	                self.open_text(TextKind::Message, &mut out);
146	                if !text.is_empty() {
147	                    self.streamed_text = true;
148	                    out.push(event::text_message_content(&self.current_message, text));
149	                }
150	            }
151	            AgentEvent::ReasoningDelta { text } => {
152	                self.close_call(&mut out);
153	                self.open_text(TextKind::Thinking, &mut out);
154	                if !text.is_empty() {
155	                    out.push(event::thinking_content(&self.current_message, text));
156	                }
157	            }
158	            AgentEvent::ToolCallDelta {
159	                call_id,
160	                name,
161	                args_delta,
162	            } => {
163	                self.close_text(&mut out);
164	                if let Some(name) = name {
165	                    self.call_names
166	                        .entry(call_id.clone())
167	                        .or_insert_with(|| name.clone());
168	                }
169	                if self.open_call.as_deref() == Some(call_id.as_str()) {
170	                    // A continuation of the currently-open call.
171	                    out.push(event::tool_call_args(call_id, args_delta));
172	                } else if self.open_call.is_none() {
173	                    // Nothing else is streaming: open this call now. If chunks for
174	                    // it were buffered while another call held the single active
175	                    // span, replay them first — they were received before this one,
176	                    // and a client concatenating `TOOL_CALL_ARGS` deltas would
177	                    // otherwise rebuild the call's arguments out of order.
178	                    let buffered = self.take_buffered(call_id);
179	                    out.push(event::tool_call_start(
180	                        call_id,
181	                        self.name_of(call_id),
182	                        &self.current_message,
183	                    ));
184	                    if let Some(buffered) = buffered {
185	                        out.push(event::tool_call_args(call_id, &buffered));
186	                    }
187	                    out.push(event::tool_call_args(call_id, args_delta));
188	                    self.open_call = Some(call_id.clone());
189	                } else {
190	                    // A different call is streaming: AG-UI permits only one active
191	                    // span, so buffer this id's content rather than interleaving a
192	                    // second START — it is flushed as a complete span once its own
193	                    // `ToolCallItem` arrives, when a later delta resumes it above,
194	                    // or at the latest when the run ends.
195	                    match self.buffered_calls.iter_mut().find(|(id, _)| id == call_id) {
196	                        Some(entry) => entry.1.push_str(args_delta),
197	                        None => self
198	                            .buffered_calls
199	                            .push((call_id.clone(), args_delta.clone())),
200	                    }
201	                }
202	            }
203	            AgentEvent::ToolCallItem { item } => {
204	                self.close_text(&mut out);
205	                if let Item::ToolCall {
206	                    call_id,
207	                    name,
208	                    args,
209	                } = item
210	                {
211	                    if self.open_call.as_deref() == Some(call_id.as_str()) {
212	                        // The call this item describes is the one currently open.
213	                        self.close_call(&mut out);
214	                    } else if let Some(buffered) = self.take_buffered(call_id) {
215	                        // Deltas for this call were buffered while another call was
216	                        // open: flush the whole thing now as one complete,
217	                        // self-contained span. Nothing guarantees `ToolCallItem`s
218	                        // arrive in the order their calls opened, so close whatever
219	                        // is still open first — a complete span emitted inside
220	                        // another one would overlap.
221	                        self.close_call(&mut out);
222	                        out.push(event::tool_call_start(call_id, name, &self.current_message));
223	                        out.push(event::tool_call_args(call_id, &buffered));
224	                        out.push(event::tool_call_end(call_id));
225	                        self.completed_calls.insert(call_id.clone());
226	                    } else if self.completed_calls.contains(call_id) {
227	                        // This call's span is already emitted and closed — by its own
228	                        // deltas above, or by a foreign event (a `TokenDelta`, another
229	                        // call's item) that had to close it to take the single active
230	                        // span. Synthesizing here would emit a second complete span
231	                        // for one call id.
232	                    } else {
233	                        // No deltas were streamed for this call (non-streaming
234	                        // provider): synthesize the whole triple from the item's own
235	                        // args so the client still sees a complete call — again, not
236	                        // nested inside whatever call is currently open.
237	                        self.close_call(&mut out);
238	                        out.push(event::tool_call_start(call_id, name, &self.current_message));
239	                        out.push(event::tool_call_args(call_id, &args.to_string()));
240	                        out.push(event::tool_call_end(call_id));
241	                        self.completed_calls.insert(call_id.clone());
242	                    }
243	                } else {
244	                    out.push(self.custom("helikon.unknown", ev));
245	                }
246	            }
247	            AgentEvent::ToolOutputItem { item } => {
248	                self.close_call(&mut out);
249	                self.close_text(&mut out);
250	                if let Item::ToolResult { call_id, content } = item {
251	                    out.push(event::tool_call_result(call_id, &text_of(content)));
252	                } else {
253	                    out.push(self.custom("helikon.unknown", ev));
254	                }
255	            }
256	            AgentEvent::MessageOutput { item } => {
257	                // Take the single active span before emitting anything: a synthesized
258	                // text triple nested inside an open `TOOL_CALL_START` would break
259	                // AG-UI's one-active-span rule.
260	                self.close_call(&mut out);
261	                if self.streamed_text {
262	                    // Deltas already streamed this text; only close it.
263	                    self.close_text(&mut out);
264	                } else {
265	                    // No deltas were emitted (non-streaming provider, workflow agent):
266	                    // synthesize the full triple, or the client renders nothing at all.
267	                    // Also closes any dangling thinking block if only `ReasoningDelta`s
268	                    // preceded this `MessageOutput` with no `TokenDelta` at all.
269	                    self.close_text(&mut out);
270	                    let content = match item {
271	                        Item::AssistantMessage { content, .. } => text_of(content),
272	                        _ => String::new(),
273	                    };
274	                    if !content.is_empty() {
275	                        let id = self.new_message_id();
276	                        out.push(event::text_message_start(&id));
277	                        out.push(event::text_message_content(&id, &content));
278	                        out.push(event::text_message_end(&id));
279	                    }
280	                }
281	                self.streamed_text = false;
282	            }
283	            AgentEvent::HandoffItem { .. } => out.push(self.custom("helikon.handoff", ev)),
284	            AgentEvent::AgentUpdated { .. } => out.push(self.custom("helikon.agent_updated", ev)),
285	            AgentEvent::GuardrailTriggered { .. } => out.push(self.custom("helikon.guardrail", ev)),
286	            AgentEvent::ApprovalRequested { .. } => out.push(self.custom("helikon.approval", ev)),
287	            AgentEvent::PermissionDenied { .. } => {
288	                out.push(self.custom("helikon.permission_denied", ev));
289	            }
290	            AgentEvent::RepairStarted { .. } => out.push(self.custom("helikon.repair", ev)),
291	            AgentEvent::StructuredOutputFailed { .. } => {
292	                out.push(self.custom("helikon.structured_output_failed", ev));
293	            }
294	            AgentEvent::RunCompleted { .. } => {
295	                self.close_all(&mut out);
296	                self.streamed_text = false;
297	                out.push(event::run_finished(&self.thread_id, &self.run_id));
298	            }
299	            AgentEvent::UserMessageInjected { .. } => {
300	                out.push(self.custom("helikon.user_message_injected", ev));
301	            }
302	            // AG-UI has no "stopped" run event. A stop is a controlled end, not a
303	            // failure, so the stream ends with `RUN_FINISHED`; the CUSTOM frame before
304	            // it carries the reason and usage.
305	            AgentEvent::RunStopped { .. } => {
306	                self.close_all(&mut out);
307	                self.streamed_text = false;
308	                out.push(self.custom("helikon.run_stopped", ev));
309	                out.push(event::run_finished(&self.thread_id, &self.run_id));
310	            }
311	            AgentEvent::RunFailed { error } => {
312	                self.close_all(&mut out);
313	                self.streamed_text = false;
314	                out.push(event::run_error("AGENT_ERROR", error));
315	            }
316	            // `AgentEvent` is `#[non_exhaustive]`: a variant added to core later must
317	            // degrade to a lossless CUSTOM event rather than vanish.
318	            other => out.push(self.custom("helikon.unknown", other)),
319	        }
320	        out
321	    }
322	
323	    /// Close any pairs still open. Only needed when a stream ends without a terminal
324	    /// event; the terminal arms already close every open pair themselves.
325	    // Called by both the AG-UI SSE endpoint (SMA-461 Task 6) and the AG-UI WebSocket
326	    // endpoint (SMA-461 Task 7) once their channel from the underlying `Agent` stream
327	    // closes, in case that stream ended without a terminal event (e.g. a misbehaving
328	    // agent, or a connection dropped mid-run).
329	    pub(crate) fn finish(&mut self) -> Vec<Value> {
330	        let mut out = Vec::new();
331	        self.close_all(&mut out);
332	        out
333	    }
334	
335	    /// Build a `CUSTOM` frame carrying the full serialized event as its `value`.
336	    fn custom(&self, name: &str, ev: &AgentEvent) -> Value {
337	        event::custom(name, to_value(ev))
338	    }
339	
340	    /// Allocate the next deterministic `msg-N` id.
341	    fn new_message_id(&mut self) -> String {
342	        let id = format!("msg-{}", self.next_message);
343	        self.next_message += 1;
344	        id
345	    }
346	
347	    /// Ensure a text-like pair of kind `kind` is open, closing any different kind
348	    /// that is currently open first. A no-op if `kind` is already open.
349	    fn open_text(&mut self, kind: TextKind, out: &mut Vec<Value>) {
350	        let target = match kind {
351	            TextKind::Message => OpenText::Message,
352	            TextKind::Thinking => OpenText::Thinking,
353	        };
354	        if self.open_text == target {
355	            return;
356	        }
357	        self.close_text(out);
358	        let id = self.new_message_id();
359	        self.current_message = id.clone();
360	        match kind {
361	            TextKind::Message => out.push(event::text_message_start(&id)),
362	            TextKind::Thinking => out.push(event::thinking_start(&id)),
363	        }
364	        self.open_text = target;
365	    }
366	
367	    /// Close whichever text-like pair is currently open, if any.
368	    fn close_text(&mut self, out: &mut Vec<Value>) {
369	        match self.open_text {
370	            OpenText::Message => out.push(event::text_message_end(&self.current_message)),
371	            OpenText::Thinking => out.push(event::thinking_end(&self.current_message)),
372	            OpenText::None => {}
373	        }
374	        self.open_text = OpenText::None;
375	    }
376	
377	    /// Close whichever tool call is currently open, if any, and record it as done so
378	    /// its `ToolCallItem` — which always arrives later — does not render it twice.
379	    fn close_call(&mut self, out: &mut Vec<Value>) {
380	        if let Some(id) = self.open_call.take() {
381	            out.push(event::tool_call_end(&id));
382	            self.completed_calls.insert(id);
383	        }
384	    }
385	
386	    /// The tool name recorded for `call_id`, falling back to `"unknown"` only when no
387	    /// delta for it ever carried one.
388	    fn name_of(&self, call_id: &str) -> &str {
389	        self.call_names
390	            .get(call_id)
391	            .map_or("unknown", String::as_str)
392	    }
393	
394	    /// Remove and return the args buffered for `call_id` while a different call held
395	    /// the active span, if any.
396	    fn take_buffered(&mut self, call_id: &str) -> Option<String> {
397	        let pos = self
398	            .buffered_calls
399	            .iter()
400	            .position(|(id, _)| id == call_id)?;
401	        Some(self.buffered_calls.remove(pos).1)
402	    }
403	
404	    /// Close a still-open `STEP_STARTED`, if any.
405	    fn close_step(&mut self, out: &mut Vec<Value>) {
406	        if self.step_open {
407	            out.push(event::step_finished("turn"));
408	            self.step_open = false;
409	        }
410	    }
411	
412	    /// Close every still-open pair: text/thinking, the open tool call, every
413	    /// still-buffered tool call (each as a complete span), then the step. Nothing
414	    /// may be left buffered once a run terminates.
415	    fn close_all(&mut self, out: &mut Vec<Value>) {
416	        self.close_text(out);
417	        self.close_call(out);
418	        for (id, args) in std::mem::take(&mut self.buffered_calls) {
419	            out.push(event::tool_call_start(
420	                &id,
421	                self.name_of(&id),
422	                &self.current_message,
423	            ));
424	            out.push(event::tool_call_args(&id, &args));
425	            out.push(event::tool_call_end(&id));
426	            self.completed_calls.insert(id);
427	        }
428	        self.close_step(out);
429	    }
430	}
431	
432	/// Serialize an event for a `CUSTOM` frame's `value`, degrading to `null` rather than
433	/// failing — a frame with a null value still tells the client the event happened.
434	fn to_value(ev: &AgentEvent) -> Value {
435	    serde_json::to_value(ev).unwrap_or(Value::Null)
436	}
437	
438	/// Concatenate the text blocks of a content list, ignoring non-text parts.
439	fn text_of(content: &[ContentPart]) -> String {
440	    content
441	        .iter()
442	        .filter_map(|c| match c {
443	            ContentPart::Text { text } => Some(text.as_str()),
444	            _ => None,
445	        })
446	        .collect()
447	}
