/// Regression (CodeRabbit, PR #186): a tool-call span must not cross a
/// `STEP_FINISHED`/`STEP_STARTED` boundary.
#[test]
fn a_tool_call_span_does_not_cross_a_turn_boundary() {
    let mut m = EventMapper::new("t".to_owned(), "r".to_owned());
    let mut frames = Vec::new();
    frames.extend(m.push(&AgentEvent::TurnStarted { turn: 1 }));
    frames.extend(m.push(&AgentEvent::ToolCallDelta {
        call_id: "tc1".to_owned(),
        name: Some("search".to_owned()),
        args_delta: "{}".to_owned(),
    }));
    frames.extend(m.push(&AgentEvent::TurnStarted { turn: 2 }));
    frames.extend(m.finish());
    assert_tool_call_nesting(&frames);
}

fn assert_tool_call_nesting(frames: &[Value]) {
    let mut open: Option<&str> = None;
    for f in frames {
        match f["type"].as_str().unwrap() {
            "TOOL_CALL_START" => {
                let id = f["toolCallId"].as_str().unwrap();
                assert!(
                    open.is_none(),
                    "TOOL_CALL_START for {id:?} while {open:?} is still open: {frames:?}"
                );
                open = Some(id);
            }
            "TOOL_CALL_ARGS" => {
                let id = f["toolCallId"].as_str().unwrap();
                assert_eq!(
                    open,
                    Some(id),
                    "TOOL_CALL_ARGS for {id:?} outside that call's own span \
                     (open: {open:?}): {frames:?}"
                );
            }
            "TOOL_CALL_END" => {
                let id = f["toolCallId"].as_str().unwrap();
                assert_eq!(
                    open,
                    Some(id),
                    "TOOL_CALL_END for {id:?} does not match the open call {open:?}: {frames:?}"
                );
                open = None;
            }
            // Nothing else may appear inside a call's span. Checking only the
            // `TOOL_CALL_*` frames would let a text triple or a step boundary nest
            // inside an open call and still pass — which is exactly how two
            // missing `close_call`s once went unnoticed here.
            other => {
                assert!(
                    open.is_none(),
                    "{other} emitted while tool call {open:?} is still open: {frames:?}"
                );
            }
        }
    }
    assert!(open.is_none(), "a tool call was left open: {frames:?}");
}

/// Assert every tool-call invariant the mapper owes an AG-UI client, for the
/// `frames` produced by `events`:
///
/// 1. spans nest and never overlap ([`assert_tool_call_nesting`]);
/// 2. each call id opens **at most once** across the whole sequence — a nesting
///    check cannot see a duplicate `START`, yet one call split across two spans
///    is exactly what breaks a client that keys state on `toolCallId`;
/// 3. each id's args are emitted **in receipt order and in full** — concatenating
///    the `TOOL_CALL_ARGS` deltas the mapper emitted for an id must reproduce the
///    concatenation of that id's `ToolCallDelta` chunks in the order they arrived.
///    Reordering or dropping a chunk yields malformed JSON on the client, and (1)
///    and (2) are both blind to it.
///
/// Ids with no `ToolCallDelta` at all (a non-streaming provider's `ToolCallItem`)
/// carry no receipt order to check, so (3) skips them.
fn assert_tool_calls_well_formed(events: &[AgentEvent], frames: &[Value]) {
    assert_tool_call_nesting(frames);

    let mut started: Vec<&str> = Vec::new();
    for f in frames.iter().filter(|f| f["type"] == "TOOL_CALL_START") {
        let id = f["toolCallId"].as_str().unwrap();
        assert!(
            !started.contains(&id),
            "TOOL_CALL_START for {id:?} emitted twice — one call must map to \
             exactly one span: {frames:?}"
        );
        started.push(id);
    }

    let mut received: BTreeMap<&str, String> = BTreeMap::new();
    for e in events {
        if let AgentEvent::ToolCallDelta {
            call_id,
            args_delta,
            ..
        } = e
        {
            received
                .entry(call_id.as_str())
                .or_default()
                .push_str(args_delta);
        }
    }
    let mut emitted: BTreeMap<&str, String> = BTreeMap::new();
    for f in frames.iter().filter(|f| f["type"] == "TOOL_CALL_ARGS") {
        emitted
            .entry(f["toolCallId"].as_str().unwrap())
            .or_default()
            .push_str(f["delta"].as_str().unwrap());
    }
    for (id, want) in &received {
        let got = emitted.get(id).map_or("", String::as_str);
        assert_eq!(
            got, want,
            "args for {id:?} must be emitted in receipt order and in full: {frames:?}"
        );
    }
}

fn assistant(text: &str) -> Item {
    Item::AssistantMessage {
        content: vec![ContentPart::Text {
            text: text.to_owned(),
        }],
        agent: None,

    pub(crate) run_id: Option<String>,
    /// The full conversation. AG-UI clients resend the entire history each request.
    #[serde(default)]
    pub(crate) messages: Vec<AgUiMessage>,
}

/// One entry in `RunAgentInput::messages`.
#[derive(Debug, Deserialize)]
pub(crate) struct AgUiMessage {
    /// Client-assigned message id. Unused by this runtime.
    // No planned caller in this plan reads a client-assigned inbound message id —
    // outbound message ids are generated fresh by the mapper (SMA-461 Task 5).
    // Kept only because the field is part of AG-UI's documented message shape.
    #[allow(dead_code)]
    #[serde(default)]
    pub(crate) id: Option<String>,
    /// `"user"`, `"assistant"`, `"system"`/`"developer"`. Any other role — including
    /// AG-UI's `"tool"` — is dropped; see [`RunAgentInput::into_agent_input`].
    pub(crate) role: String,
    /// Message text. A message without content contributes nothing.
    #[serde(default)]
    pub(crate) content: Option<String>,
}

impl RunAgentInput {
    /// Convert the whole conversation into an [`AgentInput`].
    ///
    /// AG-UI mode is stateless per request (the client owns thread state), so *every*
    /// message becomes part of the input rather than only the newest turn.
    ///
    /// # Unmodelled roles are dropped, not reassigned
    ///
    /// AG-UI defines `tool` (tool results) and `developer` alongside the three roles
    /// this runtime models. `developer` maps onto [`Item::System`]; everything else —
    /// `tool` included — is dropped. Folding an unrecognised role into a user message
    /// would be worse than losing it: a tool result relabelled as user input changes
    /// the conversation the model actually sees, and attributes to the user something
    /// they never said.
    // Both the AG-UI SSE endpoint (SMA-461 Task 6, src/agui/sse.rs) and the AG-UI
    // WebSocket endpoint (SMA-461 Task 7, src/agui/ws.rs) call this to seed the agent
    // run from the decoded request body.
    pub(crate) fn into_agent_input(self) -> AgentInput {
        let mut input = AgentInput::new();
        input.messages = self
            .messages
            .into_iter()
            .filter_map(|m| {
                let text = m.content?;
                let content = vec![ContentPart::Text { text }];
                Some(match m.role.as_str() {
                    "user" => Item::UserMessage { content },
                    "assistant" => Item::AssistantMessage {
                        content,
                        agent: None,
                    },
                    "system" | "developer" => Item::System { content },
                    // Dropped rather than misattributed — see the method docs.
                    _ => return None,
                })
            })
            .collect();
        input
    }
}

